'use client';

import React, { useState, useEffect } from 'react';
import { Navbar } from '@/components/Navbar';
import { Footer } from '@/components/Footer';
import { Book, BookLevel } from '@/lib/siteData';
import { fetchBooks } from '@/lib/supabase/actions';
import { Search, Download, ExternalLink } from 'lucide-react';

export default function BooksPage() {
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLevel, setSelectedLevel] = useState<string>('all');

  useEffect(() => {
    async function loadBooks() {
      setLoading(true);
      const data = await fetchBooks();
      setBooks(data);
      setLoading(false);
    }
    loadBooks();
  }, []);

  const filteredBooks = books.filter((book) => {
    const matchesSearch =
      book.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      book.author.toLowerCase().includes(searchQuery.toLowerCase()) ||
      book.description.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesLevel = selectedLevel === 'all' || book.level === selectedLevel;

    return matchesSearch && matchesLevel;
  });

  const getLevelLabel = (level: BookLevel) => {
    switch (level) {
      case 'beginner':
        return 'Başlanğıc səviyyə';
      case 'intermediate':
        return 'Orta səviyyə';
      case 'advanced':
        return 'İrəliləmiş səviyyə';
      default:
        return 'Ümumi';
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#0d0b17] text-[#ecebf5]">
      <Navbar />

      <main className="flex-1 py-14 px-4 sm:px-6">
        <div className="max-w-[1200px] mx-auto">
          {/* Header */}
          <div className="text-center max-w-2xl mx-auto mb-10">
            <h1 className="text-[clamp(1.85rem,3.5vw,2.5rem)] font-bold text-[#ecebf5] tracking-tight">
              Şahmat Kitabları və Dərsliklər
            </h1>
            <p className="mt-2 text-[#9893b8] text-sm sm:text-base leading-relaxed">
              Uşaqlar və yeni başlayanlar üçün seçilmiş təlim vəsaitlərini onlayn oxuyun və ya endirin.
            </p>
          </div>

          {/* Search and Filter Bar */}
          <div className="card-flat p-4 mb-8 flex flex-col md:flex-row gap-4 items-center justify-between">
            {/* Search Input */}
            <div className="relative w-full md:w-80">
              <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-[#9893b8]">
                <Search className="w-4 h-4" />
              </div>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Kitab və ya müəllif axtarın..."
                className="w-full pl-9 pr-3.5 py-2 rounded-[8px] bg-[#0d0b17] border border-[#2d2750] text-[#ecebf5] placeholder-[#9893b8]/50 focus:outline-hidden focus:border-[#7c5cff] text-xs sm:text-sm"
              />
            </div>

            {/* Level Filters */}
            <div className="flex flex-wrap items-center gap-1.5 w-full md:w-auto">
              {[
                { id: 'all', label: 'Hamısı' },
                { id: 'beginner', label: 'Başlanğıc' },
                { id: 'intermediate', label: 'Orta' },
                { id: 'advanced', label: 'İrəliləmiş' },
              ].map((item) => {
                const isActive = selectedLevel === item.id;
                return (
                  <button
                    key={item.id}
                    onClick={() => setSelectedLevel(item.id)}
                    className={`px-3 py-1.5 rounded-[8px] text-xs font-semibold transition-colors cursor-pointer ${
                      isActive
                        ? 'bg-[#7c5cff] text-white'
                        : 'bg-[#211c3a] text-[#9893b8] hover:text-[#ecebf5] border border-[#2d2750]'
                    }`}
                  >
                    {item.label}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Book Cards Grid */}
          {loading ? (
            <div className="py-20 text-center">
              <p className="text-[#9893b8] text-sm">Kitablar yüklənir...</p>
            </div>
          ) : filteredBooks.length === 0 ? (
            <div className="py-16 text-center card-flat p-8">
              <h3 className="text-base font-bold text-[#ecebf5]">Axtarışa uyğun kitab tapılmadı</h3>
              <p className="text-[#9893b8] text-xs mt-1">
                Axtarış sözünü dəyişdirin və ya filtri sıfırlayın.
              </p>
              <button
                onClick={() => {
                  setSearchQuery('');
                  setSelectedLevel('all');
                }}
                className="btn-secondary px-3.5 py-1.5 text-xs mt-3 cursor-pointer"
              >
                Filtri sıfırla
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
              {filteredBooks.map((book) => (
                <div
                  key={book.id}
                  className="card-flat p-5 flex flex-col justify-between"
                >
                  <div>
                    {/* Quiet text metadata */}
                    <div className="flex items-center gap-2 text-xs text-[#9893b8] mb-2.5">
                      <span className="text-[#7c5cff] font-medium">{getLevelLabel(book.level)}</span>
                      <span aria-hidden="true">·</span>
                      <span>PDF dərslik</span>
                    </div>

                    <h3 className="text-base font-bold text-[#ecebf5] mb-1 leading-snug">
                      {book.title}
                    </h3>
                    <p className="text-xs text-[#9893b8] font-medium mb-3">
                      Müəllif: {book.author}
                    </p>

                    <p className="text-xs text-[#9893b8] leading-relaxed line-clamp-3 mb-5">
                      {book.description}
                    </p>
                  </div>

                  {/* Actions */}
                  <div className="pt-3 border-t border-[#2d2750] flex items-center gap-2">
                    <a
                      href={book.file_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="btn-primary flex-1 py-2 px-3 text-xs"
                    >
                      <ExternalLink className="w-3.5 h-3.5 mr-1.5" />
                      <span>Oxu / Bax</span>
                    </a>
                    <a
                      href={book.file_url}
                      download={book.file_name || 'sahmat_kitabi.pdf'}
                      className="btn-secondary py-2 px-3 text-xs"
                      title="PDF kimi yüklə"
                    >
                      <Download className="w-3.5 h-3.5" />
                    </a>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>

      <Footer />
    </div>
  );
}
